import{_ as e,o as i,c as t,a as r}from"./app-4e02db32.js";const a={},o=r('<h1 id="postgresql执行计划" tabindex="-1"><a class="header-anchor" href="#postgresql执行计划" aria-hidden="true">#</a> PostgreSQL执行计划</h1><h2 id="总体思路" tabindex="-1"><a class="header-anchor" href="#总体思路" aria-hidden="true">#</a> 总体思路</h2><ol><li>先看底部的 Execution Time：知道总耗时。</li><li>从下往上找 actual time 最大的节点：谁最耗时，谁就是嫌疑人。</li><li>盯着 loops= 看：如果 loops 很大，乘以单次时间，就是总灾难时间。</li><li>盯着 Seq Scan（全表扫描）看：大表上面看到这个，立刻找 Filter 里的字段，去建索引！</li><li>看 Rows Removed by Filter：这个数字越大，说明白扫的行数越多，越需要索引。</li></ol><h2 id="大表定义" tabindex="-1"><a class="header-anchor" href="#大表定义" aria-hidden="true">#</a> 大表定义</h2><ul><li><strong>小表（1万 - 50万行）</strong>：随便造，全表扫也就几十毫秒。</li><li><strong>中表（50万 - 1000万行）</strong>：开始需要认真建索引了，乱写 SQL 会卡顿。</li><li><strong>大表（1000万 - 1亿行）</strong>：属于绝对的大表。必须精细化建索引，复杂查询要考虑分区（Partitioning）或者物化视图。</li><li><strong>超大表（1亿行以上）</strong>：没有分区、没有冷热数据分离，基本没法玩。</li></ul>',5),l=[o];function s(n,h){return i(),t("div",null,l)}const d=e(a,[["render",s],["__file","PostgreSQLzhixingjihua.html.vue"]]);export{d as default};
